// Customer design system; staff operations retain their existing layouts.
paths.plus='M12 5v14M5 12h14';
const staffNavigation=navItems;
navItems=function(){return state.role==='Customer'?[['home','home','Home'],['bookings','calendar','Visits'],['book','plus','Book'],['messages','message','Messages'],['more','users','Account']]:staffNavigation();};
function customerRow(label,page,type){return `<button class="customer-menu-row" data-customer="page" data-page="${page}">${icon(type)}<span>${label}</span>${icon('chevron')}</button>`;}
function customerReward(compact=false){return `<section class="panel customer-reward ${compact?'compact':''}"><button class="customer-reward-heading" data-customer="page" data-page="rewards">${icon('gift')}<span><strong>The Fresh Cut Club</strong><small>${extras.punches} of 10 stamps</small></span>${icon('chevron')}</button><div class="customer-stamps">${Array.from({length:10},(_,i)=>`<span class="${i<extras.punches?'filled':''}" aria-label="Visit ${i+1}${i<extras.punches?', stamped':''}">${i<extras.punches?icon('scissors'):i===4?'50%':i===9?'FREE':i+1}</span>`).join('')}</div><p>5th cut half off. 10th cut free.</p></section>`;}
const staffDirectory=directory;
directory=function(){if(state.role!=='Customer')return staffDirectory();return `${head('Your account','')}<section class="panel customer-account"><button class="customer-identity" data-customer="page" data-page="cProfile">${clientPhoto('John B.')}<span><strong>${esc(extras.profile.name||'John B.')}</strong><small>Your next great cut starts here.</small></span>${icon('chevron')}</button>${customerRow('My appointments','bookings','calendar')}${customerRow('Payment methods','cPayments','card')}${customerRow('Help & support','cHelp','message')}</section>${customerReward()}<section class="panel customer-memory-link">${customerRow('Remember this cut','customerMemories','camera')}<p>Your photos and notes, ready for next time.</p></section>`;};
function customerAppointment(b){const barber=barbers.find(x=>x.id===b.barber),complete=b.status==='completed'||b.ticket?.approval,paid=b.settlement?.status==='paid';return `<article class="panel customer-visit"><div class="row between"><small>${pretty(b.date)} · ${esc(b.time)}</small><span class="badge ${b.status==='cancelled'?'cancelled':''}">${b.status==='cancelled'?'Cancelled':complete?'Completed':b.status==='pending_payment'?'Pending prepayment':'Confirmed'}</span></div><div class="customer-visit-person"><h2>${esc(bookingName(b))}</h2><div class="customer-visit-barber">${photo(barber)}<span>${esc(barber.name)} · ${esc(shops[b.location||extras.location]?.name||'Shop')}</span></div><small>${bookingDuration(b)} min · ${cents(b.ticket?.approval?.totalCents??b.estimateCents)}</small></div>${complete?`<div class="customer-visit-actions"><button data-customer="receipt" data-id="${esc(b.id)}">${icon('card')} View receipt ${icon('chevron')}</button><button data-customer="feedback" data-id="${esc(b.id)}">${icon('star')} Private feedback</button></div><small>${paid?'Payment recorded':'Services approved · payment not recorded'}</small>`:`${appointmentActions(b)}${b.status!=='cancelled'?`<button class="customer-message-link" data-customer="message" data-barber-id="${barber.id}">${icon('message')} Message ${esc(barber.short)} ${icon('arrow')}</button>`:''}`}</article>`;}
customerHome=function(){const next=upcoming();return `${head('Looking sharp, '+esc((extras.profile.name||'John').split(' ')[0])+'.','Your next great cut starts here.')} ${next?`<section class="customer-next"><h2>Your next visit</h2>${customerAppointment(next)}</section>`:`<section class="panel customer-welcome"><h2>A familiar chair.<br>A fresh perspective.</h2><p>Choose your barber and make time for yourself.</p><button class="btn full" data-action="start">${icon('calendar')} Book your next visit ${icon('arrow')}</button></section>`}<section class="customer-photo-banner"><img src="assets/shop.jpg" alt="The craft of a good haircut"><h2>Your barber.<br>Your kind of cut.</h2></section><section class="panel customer-people"><h2>Your people</h2>${barbers.map(b=>`<button class="customer-barber-row" data-x="barber-profile" data-id="${b.id}">${photo(b)}<span><strong>${esc(b.name)}</strong><small>${openingLabel(b.id)}</small></span>${icon('chevron')}</button>`).join('')}</section>${customerReward(true)}`;};
barberProfile=function(){const b=B();return `${head('Meet '+esc(b.short)+'.','',linkPage('All barbers','cSearch','Customer'))}<section class="panel customer-profile"><div class="customer-profile-heading">${photo(b,'profile-portrait')}<div><h2>${esc(b.name)}</h2><p>Barber · HAIRFLIX</p><small>${icon('pin')} ${esc(shops[extras.location].name)}</small><p>Precision cuts. A familiar chair.</p></div></div><div class="customer-profile-actions">${xbutton(icon('calendar')+' Book '+esc(b.short),'book-barber')}${xbutton(icon('message')+' Message','message-barber','secondary')}${xbutton(icon('star')+(extras.saved.includes(b.id)?' Favorited':' Favorite'),'save-barber','secondary')}</div></section>${portfolioGallery(b.id)}<section class="panel customer-service-menu"><h2>Services</h2>${servicesFor(b.id).filter(s=>s.active!==false).map(s=>`<button data-business="choose-service" data-id="${s.id}">${serviceIcon(s)}<span>${esc(s.name)}<small>${s.min} min</small></span><strong>${money(s.price)}</strong>${icon('chevron')}</button>`).join('')}</section>`;};
function customerShopCard(location){const id=location||extras.location,address=shopAddresses[id],query=encodeURIComponent('Hairflix Barbershop '+address);return `<section class="panel customer-shop-card"><h2>${icon('pin')} Your shop</h2><p>HAIRFLIX · ${esc(shops[id].name)}</p><address>${esc(address)}</address><iframe title="Map of your booked shop" loading="lazy" src="https://maps.google.com/maps?q=${query}&output=embed" referrerpolicy="no-referrer"></iframe><a href="https://www.google.com/maps/search/?api=1&query=${query}" target="_blank" rel="noopener noreferrer">Get directions ${icon('arrow')}</a></section>`;}
myBookings=function(){const past=state.customerVisitTab==='past',list=bookings.filter(b=>b.client==='John B.'&&(past?b.status==='completed'||b.ticket?.approval||b.status==='cancelled':b.status!=='completed'&&!b.ticket?.approval&&b.status!=='cancelled')).sort((a,b)=>past?b.date.localeCompare(a.date)||minutes(b.time)-minutes(a.time):a.date.localeCompare(b.date)||minutes(a.time)-minutes(b.time));return `${head('Your time in the chair.','')}<div class="customer-tabs"><button data-customer="visits" data-tab="upcoming" aria-pressed="${!past}">Upcoming</button><button data-customer="visits" data-tab="past" aria-pressed="${past}">Past</button></div>${list.length?list.map(customerAppointment).join(''):`<section class="panel customer-empty"><h2>${past?'Your visits, remembered.':'Make time for your next cut.'}</h2><p>${past?'Completed visits and receipts will appear here.':'Your next appointment is a few taps away.'}</p>${past?'':'<button class="btn" data-action="start">Book a visit</button>'}</section>`}${!past&&list[0]?customerShopCard(list[0].location):''}<details class="panel customer-policy"><summary>Reschedule/Cancellation Policy</summary><p>${policySummary(list[0]||{estimateCents:0})}</p></details><section class="panel customer-memory-link">${customerRow('Remember your last cut','customerMemories','camera')}<p>Photos & notes</p></section>`;};
const extraBeforeCustomer=renderExtraView;renderExtraView=function(v){if(state.role==='Customer'&&v==='customerMemories'){const visits=bookings.filter(b=>b.client==='John B.'&&(b.status==='completed'||b.ticket?.approval));return `${head('Remember this cut.','Your photos and notes, ready for next time.')}${visits.map(b=>`<p class="customer-memory-date">${pretty(b.date)} · ${esc(bookingName(b))}</p>${memoryPanel(b)}`).join('')||'<section class="panel customer-empty"><h2>A cut worth keeping.</h2><p>After your completed visit, save photos and notes here.</p></section>'}`;}if(state.role==='Customer'&&v==='rewards')return head('The Fresh Cut Club','One stamp per completed, approved visit.')+customerReward();return extraBeforeCustomer(v);};
const renderBeforeCustomer=render;
render=function(){renderBeforeCustomer();document.body.dataset.customer=state.role==='Customer'?'true':'false';if(state.role!=='Customer')return;
 const top=document.querySelector('.topbar');top?.insertAdjacentHTML('afterbegin',`<button class="customer-brand" data-view="home" aria-label="Hairflix home"><span class="customer-pole" aria-hidden="true"></span><span>HAIRFLIX</span></button>`);document.querySelector('.topbar .mobile-brand')?.remove();document.querySelector('.topbar .location')?.remove();document.querySelector('.store-label')?.remove();document.querySelector('.topbar .account-avatar-button')?.remove();
 if(state.view==='book'&&state.step===2){const list=document.querySelector('.booking-time-options'),groups=[...(list?.querySelectorAll('.time-period')||[])];if(groups.length){const labels=groups.map(g=>g.querySelector('h3').textContent);const chosen=labels.includes(state.customerTimePeriod)?state.customerTimePeriod:labels.includes('Afternoon')?'Afternoon':labels[0];list.insertAdjacentHTML('afterbegin',`<div class="customer-time-tabs" role="group" aria-label="Time of day">${labels.map(label=>`<button data-customer="time-period" data-period="${label}" aria-pressed="${label===chosen}">${label}</button>`).join('')}</div>`);groups.forEach(g=>g.hidden=g.querySelector('h3').textContent!==chosen);}}
 const nav=document.querySelector('.bottom-nav');nav?.classList.add('customer-nav');const book=nav?.querySelector('[data-view=book]');book?.classList.add('customer-book-action');
 const group=['cProfile','cPayments','cNotifications','cHelp','customerMemories','rewards','more'].includes(state.view)?'more':['success','book','cBarberProfile','cSearch','cServices'].includes(state.view)?'book':['bookings','cReceipt','cReview','cApproval'].includes(state.view)?'bookings':state.view;
 nav?.querySelectorAll('[data-view]').forEach(el=>{el.classList.toggle('active',el.dataset.view===group);if(el.dataset.view===group)el.setAttribute('aria-current','page');else el.removeAttribute('aria-current');});
};
document.addEventListener('click',e=>{const el=e.target.closest('[data-customer]');if(!el||state.role!=='Customer')return;const d=el.dataset;switch(d.customer){case'time-period':state.customerTimePeriod=d.period;render();break;case'page':go(d.page);break;case'visits':state.customerVisitTab=d.tab;render();break;case'message':state.barber=d.barberId;state.threadId=threadFor('John B.',d.barberId).id;state.chatOpen=true;save();go('messages');break;case'receipt':state.visitId=d.id;go('cReceipt');break;case'feedback':state.visitId=d.id;go('cReview');break;}});
render();
